package ru.wibestyle.api.controller;
import org.springframework.core.io.FileSystemResource; import org.springframework.core.io.Resource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import ru.wibestyle.api.storage.*; import ru.wibestyle.api.support.AuthSupport; import java.util.*;
@RestController @RequestMapping("/api/v1/profile/hairstyle-portrait") public class HairstylePortraitController { final BlobStorage s; public HairstylePortraitController(BlobStorage s){this.s=s;} private UUID u(String h){return AuthSupport.requireUserId(h);} @PostMapping public Map<String,Object> upload(@RequestHeader(value="Authorization",required=false)String h,@RequestParam MultipartFile portrait)throws Exception{UUID u=u(h);if(portrait.isEmpty()||portrait.getSize()>10*1024*1024)throw new IllegalArgumentException("PORTRAIT_INVALID");s.put(BlobKeys.hairstylePortrait(u),portrait.getInputStream());return Map.of("imageUrl","/api/v1/profile/hairstyle-portrait/image");} @GetMapping("/image") public ResponseEntity<Resource> image(@RequestHeader(value="Authorization",required=false)String h){UUID u=u(h);var p=s.resolveLocalFile(BlobKeys.hairstylePortrait(u));return ResponseEntity.ok().contentType(MediaType.IMAGE_JPEG).body(new FileSystemResource(p));}}
